<template>
  <button class="museum-sheet-handle" type="button" :aria-label="`${expanded?'Reduce':'Expand'} ${label}`" :aria-expanded="expanded" data-press-intent="custom"
    @pointerdown="start" @pointermove="move" @pointerup="end" @pointercancel="cancel" @lostpointercapture="cancel" @click="keyboardToggle"><span aria-hidden="true"/></button>
</template>
<script setup>
/* global defineProps, defineEmits */
import {nextTick,onBeforeUnmount} from 'vue';
import {animate} from 'motion';
const props=defineProps({expanded:Boolean,label:{type:String,default:'reading panel'}}),emit=defineEmits(['toggle']);
let drag=null,animation=null,sheet=null,restore=null;
function release(){animation?.stop();animation=null;if(sheet&&restore){sheet.style.height=restore.height;sheet.style.top=restore.top;sheet.style.transition=restore.transition;sheet.style.maxHeight=restore.maxHeight;sheet.classList.remove('is-sheet-dragging');}restore=null;sheet=null;}
function start(event){if(event.button!==0)return;const current=event.currentTarget.closest('[data-museum-sheet]');if(!current)return;const height=current.getBoundingClientRect().height;animation?.stop();if(sheet!==current){release();sheet=current;}if(!restore)restore={height:sheet.style.height,top:sheet.style.top,transition:sheet.style.transition,maxHeight:sheet.style.maxHeight};const bottom=sheet.getBoundingClientRect().bottom;sheet.classList.add('is-sheet-dragging');sheet.style.top='auto';sheet.style.height=`${height}px`;sheet.style.transition='none';sheet.style.maxHeight=`${Math.max(120,bottom-76)}px`;drag={id:event.pointerId,y:event.clientY,last:event.clientY,at:event.timeStamp,height,current:height,velocity:0,max:Math.max(120,bottom-76),moved:false};event.currentTarget.setPointerCapture(event.pointerId);}
function move(event){if(!drag||event.pointerId!==drag.id)return;const delta=drag.y-event.clientY;drag.moved ||= Math.abs(delta)>6;drag.velocity=(drag.last-event.clientY)/Math.max(1,event.timeStamp-drag.at);drag.last=event.clientY;drag.at=event.timeStamp;drag.current=Math.max(110,Math.min(drag.max,drag.height+delta));sheet.style.height=`${drag.current}px`;}
async function settle(change,velocity=0){if(!sheet)return;const card=sheet,from=card.getBoundingClientRect().height,saved=restore;drag=null;card.classList.remove('is-sheet-dragging');if(change)emit('toggle');await nextTick();if(sheet!==card||!saved)return;card.style.height=saved.height;card.style.top=saved.top;card.style.maxHeight=saved.maxHeight;const target=card.getBoundingClientRect().height;card.style.top='auto';card.style.height=`${from}px`;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){release();return;}animation=animate(from,target,{type:'spring',stiffness:420,damping:42,velocity:velocity*1000,onUpdate:value=>{card.style.height=`${value}px`;},onComplete:release});}
function end(event){if(!drag||event.pointerId!==drag.id)return;const state=drag,delta=state.y-event.clientY,velocity=event.timeStamp-state.at<100?state.velocity:0;const wantsExpanded=state.moved?(Math.abs(velocity)>.2?velocity>0:delta>0):!props.expanded;settle(wantsExpanded!==props.expanded,velocity);if(event.currentTarget.hasPointerCapture(event.pointerId))event.currentTarget.releasePointerCapture(event.pointerId);}
function cancel(){if(drag)settle(false);}
function keyboardToggle(event){if(event.detail===0)emit('toggle');}
onBeforeUnmount(release);
</script>
<style scoped>
.museum-sheet-handle{display:none}
@media(max-width:767px) and (orientation:portrait){.museum-sheet-handle{display:grid;place-items:center;position:absolute;z-index:9;top:2px;left:50%;transform:translateX(-50%);width:70px;height:32px;border:0;padding:0;background:transparent;color:var(--ex-muted);cursor:ns-resize;touch-action:none;user-select:none}.museum-sheet-handle>span{width:32px;height:3px;border-radius:3px;background:currentColor;opacity:.35;transition:opacity 100ms}.museum-sheet-handle:active>span,.museum-sheet-handle:focus-visible>span{opacity:.8}.museum-sheet-handle:focus-visible{outline:1px solid currentColor;outline-offset:-3px}}
</style>
